class BlocksRec {
  private long roof(int i) {
    if (i == 1) {
      return 1;
    }
    return roof(i - 1) * 2 + 1;
  }

  private long blocksRec(int n) {
    if (n == 1) {
      return 1;
    }
    return blocksRec(n - 1) * 2 + roof(n);
  }

  public long solve(int n) {
    return blocksRec(n);
  }
}
class BlocksMemoized {
  private HashMap<Integer, Long> memo;

  public long solve(int n) {
    memo = new HashMap<>();
    return blocksRec(n);
  }

  private long roof(int i) {
    if (i == 1) {
      return 1;
    }
    if (memo.containsKey(i)) {
      return memo.get(i);
    }
    long result = roof(i - 1) * 2 + 1;
    memo.put(i, result);
    return result;
  }

  private long blocksRec(int n) {
    if (n == 1) {
      return 1;
    }
    return blocksRec(n - 1) * 2 + roof(n);
  }
}

class BlocksIterative {
  public long solve(int n) {
    long blocks = 1;
    for (int i = 2; i <= n; i++) {
      long roof = (1L << i) - 1;
      blocks = blocks * 2 + roof;
    }
    return blocks;
  }
}

class BlocksMath {
  public long solve(int n) {
    long power = 1L << n;
    return n * power - (power - 1);
  }
}

